init:
ChartKit.penaltyRewardMap('c-penalty-reward-map', DEMO.penaltyRewardMap());
const host = document.getElementById('c-penalty-reward-map'), grid = document.createElement('div');
grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px;margin-top:14px';
host.parentNode.insertBefore(grid, host.nextSibling.nextSibling);
DEMO.penaltyRewardMapGroups().forEach(g => { const cell = document.createElement('div'); cell.innerHTML = '<div style="font-size:.86rem;font-weight:700;margin:0 0 2px">' + g.title + '</div><div style="height:230px"></div>'; grid.appendChild(cell); ChartKit.penaltyRewardMap(cell.lastChild, { ...g.opts, highlight: 'Pool or gym' }); });

